# -*- coding: utf-8 -*-
"""Gerber RS-274X 写出器（支持 LPD/LPC 极性、G36 区域、圆形孔径）"""
import math

S = 1000000


def c(v):
    return str(int(round(v * S)))


class Grb:
    def __init__(self, title, layer_note=""):
        self.L = [
            f"G04 {title}*",
            "G04 Kisara PCB pendant, generated by WorkBuddy*",
            f"G04 {layer_note}*" if layer_note else "G04 *",
            "%TF.GenerationSoftware,WorkBuddy,KisaraMedallion,2.0*%",
            "%TF.SameCoordinates,Original*%",
            "%FSLAX46Y46*%",
            "%MOMM*%",
            "%LPD*%",
        ]
        self.cur_pol = "D"
        self.ap = {}
        self.cur_ap = None

    # ---------------- 极性
    def pol(self, p):
        if p != self.cur_pol:
            self.L.append(f"%LP{p}*%")
            self.cur_pol = p

    # ---------------- 孔径
    def circle_ap(self, d_mm):
        key = f"C{d_mm:.4f}"
        if key in self.ap:
            return self.ap[key]
        code = 10 + len(self.ap)
        self.ap[key] = code
        self.L.append(f"%ADD{code}C,{d_mm:.4f}*%")
        return code

    def select(self, code):
        if self.cur_ap != code:
            self.L.append(f"D{code}*")
            self.cur_ap = code

    # ---------------- 图形
    def region(self, pts):
        if len(pts) < 3:
            return
        self.L.append("G36*")
        x0, y0 = pts[0]
        self.L.append(f"X{c(x0)}Y{c(y0)}D02*")
        for x, y in pts[1:]:
            self.L.append(f"X{c(x)}Y{c(y)}D01*")
        self.L.append(f"X{c(x0)}Y{c(y0)}D01*")
        self.L.append("G37*")

    def path(self, pts, d_mm):
        code = self.circle_ap(d_mm)
        self.select(code)
        pts = list(pts)
        x0, y0 = pts[0]
        self.L.append(f"X{c(x0)}Y{c(y0)}D02*")
        for x, y in pts[1:]:
            self.L.append(f"X{c(x)}Y{c(y)}D01*")

    def flash(self, x, y, d_mm):
        code = self.circle_ap(d_mm)
        self.select(code)
        self.L.append(f"X{c(x)}Y{c(y)}D03*")

    def save(self, path):
        with open(path, "w", encoding="ascii", newline="\n") as f:
            f.write("\n".join(self.L + ["M02*"]))


def point_in_poly(pt, poly):
    x, y = pt
    inside = False
    n = len(poly)
    j = n - 1
    for i in range(n):
        xi, yi = poly[i]
        xj, yj = poly[j]
        if ((yi > y) != (yj > y)) and \
           (x < (xj - xi) * (y - yi) / (yj - yi + 1e-12) + xi):
            inside = not inside
        j = i
    return inside


def ring_area(r):
    s = 0.0
    n = len(r)
    for i in range(n):
        x1, y1 = r[i]
        x2, y2 = r[(i + 1) % n]
        s += x1 * y2 - x2 * y1
    return s / 2.0


def emit_rings(g, rings):
    """
    环按嵌套深度决定极性：偶数层 LPD（画），奇数层 LPC（挖）。
    按深度从浅到深依次输出，保证挖孔在填充之后。
    """
    items = []
    for r in rings:
        xs = [p[0] for p in r]
        ys = [p[1] for p in r]
        items.append({
            "r": r,
            "a": abs(ring_area(r)),
            "bb": (min(xs), min(ys), max(xs), max(ys)),
            "d": 0,
        })
    items.sort(key=lambda t: -t["a"])
    for i, it in enumerate(items):
        px, py = it["r"][0]
        d = 0
        for j, o in enumerate(items):
            if i == j or o["a"] <= it["a"]:
                continue
            x0, y0, x1, y1 = o["bb"]
            if x0 <= px <= x1 and y0 <= py <= y1:
                if point_in_poly((px, py), o["r"]):
                    d += 1
        it["d"] = d

    for depth in range(0, 12):
        group = [t for t in items if t["d"] == depth]
        if not group:
            continue
        g.pol("D" if depth % 2 == 0 else "C")
        for t in group:
            g.region(t["r"])
    g.pol("D")
